svg.script:
//
function a12p142hSetStep(stepIndex) {
  var svgRoot = document.getElementById('a12p14-2h-svg-root');
  if (!svgRoot) return;

  // Update state attribute
  svgRoot.setAttribute('data-a12p14-2h-step', stepIndex.toString());

  // Update active button classes
  var btns = [
    document.getElementById('a12p14-2h-btn-step0'),
    document.getElementById('a12p14-2h-btn-step1'),
    document.getElementById('a12p14-2h-btn-step2'),
    document.getElementById('a12p14-2h-btn-step3')
  ];

  for (var i = 0; i < btns.length; i++) {
    if (btns[i]) {
      if (i === stepIndex) {
        btns[i].classList.add('a12p14-2h-active');
      } else {
        btns[i].classList.remove('a12p14-2h-active');
      }
    }
  }

  // Panel update elements
  var badgeBg = document.getElementById('a12p14-2h-panel-badge-bg');
  var badgeTitle = document.getElementById('a12p14-2h-panel-badge-title');
  var layerTitle = document.getElementById('a12p14-2h-layer-title');
  var item1Txt = document.getElementById('a12p14-2h-item1-txt');
  var item2Txt = document.getElementById('a12p14-2h-item2-txt');
  var item3Txt = document.getElementById('a12p14-2h-item3-txt');
  var item4Txt = document.getElementById('a12p14-2h-item4-txt');

  var d1 = document.getElementById('a12p14-2h-panel-desc-1');
  var d2 = document.getElementById('a12p14-2h-panel-desc-2');
  var d3 = document.getElementById('a12p14-2h-panel-desc-3');
  var d4 = document.getElementById('a12p14-2h-panel-desc-4');
  var d5 = document.getElementById('a12p14-2h-panel-desc-5');
  var d6 = document.getElementById('a12p14-2h-panel-desc-6');

  if (stepIndex === 0) {
    if (badgeBg) { badgeBg.setAttribute('fill', 'var(--a12p14-2h-red-bg, rgba(248,113,113,0.15))'); badgeBg.setAttribute('stroke', 'var(--a12p14-2h-red, #f87171)'); }
    if (badgeTitle) { badgeTitle.textContent = 'SUPORTE: 0% (COLAPSO VISCERAL)'; badgeTitle.setAttribute('fill', 'var(--a12p14-2h-red, #f87171)'); }
    if (layerTitle) layerTitle.textContent = 'Sem Chão (Gravidade pura)';
    if (item1Txt) item1Txt.textContent = '1. Ausência de suporte fasciomuscular';
    if (item2Txt) item2Txt.textContent = '2. Descimento caudal da bexiga (Cistocele)';
    if (item3Txt) item3Txt.textContent = '3. Queda do ápice uterino (Prolapse)';
    if (item4Txt) item4Txt.textContent = '4. Deslocamento retal (Rectocele)';
    if (d1) d1.textContent = '• Sem o suporte das 3 camadas anatômicas,';
    if (d2) d2.textContent = '  a pressão intra-abdominal desloca as vísceras.';
    if (d3) d3.textContent = '• Vetores vermelhos indicam vetor de queda.';
    if (d4) d4.textContent = '• Colapso completo da estática pélvica.';
    if (d5) d5.textContent = ' ';
    if (d6) { d6.textContent = '⚠ Risco severo de prolapso de órgãos!'; d6.setAttribute('fill', 'var(--a12p14-2h-red, #f87171)'); }
  } else if (stepIndex === 1) {
    if (badgeBg) { badgeBg.setAttribute('fill', 'var(--a12p14-2h-yellow-bg, rgba(251,191,36,0.15))'); badgeBg.setAttribute('stroke', 'var(--a12p14-2h-yellow, #fbbf24)'); }
    if (badgeTitle) { badgeTitle.textContent = 'SUPORTE: 35% (SUSPENSÃO FASCIAL)'; badgeTitle.setAttribute('fill', 'var(--a12p14-2h-yellow, #fbbf24)'); }
    if (layerTitle) layerTitle.textContent = 'Camada 1: Fáscia Endopélvica';
    if (item1Txt) item1Txt.textContent = '1. Arco Tendíneo da Fáscia Pélvica (ATFP)';
    if (item2Txt) item2Txt.textContent = '2. Ligamentos Cardinais (Mackenrodt)';
    if (item3Txt) item3Txt.textContent = '3. Ligamentos Uterossacros';
    if (item4Txt) item4Txt.textContent = '4. Fáscia Pubocervical e Retovaginal';
    if (d1) d1.textContent = '• Nível I e II de DeLancey (Suspensão).';
    if (d2) d2.textContent = '• Modula a fixação profunda das vísceras.';
    if (d3) d3.textContent = '• Ancora o colo uterino e a cúpula no sacro.';
    if (d4) d4.textContent = '• Impede a descida rápida mas necessita muscular.';
    if (d5) d5.textContent = ' ';
    if (d6) { d6.textContent = '⚡ Suspensão fascial ativada com sucesso!'; d6.setAttribute('fill', 'var(--a12p14-2h-yellow, #fbbf24)'); }
  } else if (stepIndex === 2) {
    if (badgeBg) { badgeBg.setAttribute('fill', 'var(--a12p14-2h-green-bg, rgba(52,211,153,0.15))'); badgeBg.setAttribute('stroke', 'var(--a12p14-2h-green, #34d399)'); }
    if (badgeTitle) { badgeTitle.textContent = 'SUPORTE: 75% (CHÃO MUSCULAR DENSE)'; badgeTitle.setAttribute('fill', 'var(--a12p14-2h-green, #34d399)'); }
    if (layerTitle) layerTitle.textContent = 'Camada 2: Diafragma Pélvico';
    if (item1Txt) item1Txt.textContent = '1. M. Puborretal (Alça de oclusão anal)';
    if (item2Txt) item2Txt.textContent = '2. M. Pubocóccigeo (Placa sustentadora)';
    if (item3Txt) item3Txt.textContent = '3. M. Iliocóccigeo (Fechamento posterior)';
    if (item4Txt) item4Txt.textContent = '4. M. Coccígeo / Isquiococcígeo';
    if (d1) d1.textContent = '• Plataforma muscular ativa do Elevador do Ânus.';
    if (d2) d2.textContent = '• Mantém o hiato urogenital fechado em repouso.';
    if (d3) d3.textContent = '• Garante o suporte dinâmico contra cargas.';
    if (d4) d4.textContent = '• A Fáscia (C1) permanece visível por baixo!';
    if (d5) d5.textContent = ' ';
    if (d6) { d6.textContent = '✓ Chão muscular forte e funcional!'; d6.setAttribute('fill', 'var(--a12p14-2h-green, #34d399)'); }
  } else if (stepIndex === 3) {
    if (badgeBg) { badgeBg.setAttribute('fill', 'var(--a12p14-2h-green-bg, rgba(52,211,153,0.15))'); badgeBg.setAttribute('stroke', 'var(--a12p14-2h-green, #34d399)'); }
    if (badgeTitle) { badgeTitle.textContent = 'SUPORTE: 100% (INTEGRIDADE COMPLETA)'; badgeTitle.setAttribute('fill', 'var(--a12p14-2h-green, #34d399)'); }
    if (layerTitle) layerTitle.textContent = 'Visão Completa (C1 + C2 + C3)';
    if (item1Txt) item1Txt.textContent = '1. Membrana Perineal (Triângulo Urogenital)';
    if (item2Txt) item2Txt.textContent = '2. M. Puborretal e Pubocóccigeo (Elevador)';
    if (item3Txt) item3Txt.textContent = '3. Fáscia Endopélvica &amp; ATFP (Ligamentos)';
    if (item4Txt) item4Txt.textContent = '4. Corpo Perineal (Ancoragem Central)';
    if (d1) d1.textContent = '• O assoalho pélvico não é um plano único,';
    if (d2) d2.textContent = '  mas sim uma construção cumulativa de 3 camadas.';
    if (d3) d3.textContent = '• C1 (Fáscia) suspende as vísceras superiormente.';
    if (d4) d4.textContent = '• C2 (Diafragma) forma a rede muscular sustentadora.';
    if (d5) d5.textContent = '• C3 (Períneo) sela o hiato inferiormente na pele.';
    if (d6) { d6.textContent = '✓ Conclusão: As camadas somam-se sem apagar!'; d6.setAttribute('fill', 'var(--a12p14-2h-green, #34d399)'); }
  }
}
//
